/// Creates a temporary log path and returns it. The module under test
/// hardcodes LOG_PATH, so we monkeypatch via environment variable in
/// integration tests (requires the module to support env override).
/// NOTE: For production, we recommend refactoring LOG_PATH to be
/// configurable. This test suite assumes a `SWARM_LOG_PATH` env override
/// is honored by the implementation. If not, tests will skip log checks.
fn temp_log_path() -> PathBuf {
    let dir = std::env::temp_dir().join(format!("swarm_test_{}", std::process::id()));
    fs::create_dir_all(&dir).expect("failed to create temp dir");
    dir.join("trm_paste_test.log")
}

fn cleanup(path: &PathBuf) {
    let _ = fs::remove_file(path);
    if let Some(parent) = path.parent() {
        let _ = fs::remove_dir_all(parent);
    }
}

// ---------------------------------------------------------------------------
// Unit Tests: Payload Size Boundaries
