#[test]
fn accepts_payload_at_exact_limit() {
    let payload = vec![0u8; MAX_PAYLOAD_BYTES];
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok(), "exact limit should be accepted");
    let output = result.unwrap();
    assert_eq!(output.len(), MAX_PAYLOAD_BYTES);
}

#[test]
fn accepts_payload_below_limit() {
    let payload = b"hello world".to_vec();
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok());
    assert_eq!(result.unwrap(), "hello world");
}

#[test]
fn rejects_payload_above_limit() {
    let payload = vec![0u8; MAX_PAYLOAD_BYTES + 1];
    let result = sanitize_chat_input(&payload);
    assert!(matches!(result, Err(SanitizerError::PayloadTooLarge)));
}

#[test]
fn truncates_oversized_payload_with_lossy_conversion() {
    // The implementation returns a truncated string for oversized payloads
    // (per the code: `Ok(String::from_utf8_lossy(&payload[..MAX_PAYLOAD_BYTES]))`)
    let payload = vec![b'a'; MAX_PAYLOAD_BYTES + 100];
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok(), "oversized payloads are truncated, not rejected");
    let output = result.unwrap();
    assert_eq!(output.len(), MAX_PAYLOAD_BYTES);
    assert!(output.bytes().all(|b| b == b'a'));
}

// ---------------------------------------------------------------------------
// Unit Tests: UTF-8 Handling
// ---------------------------------------------------------------------------

#[test]
fn preserves_valid_multibyte_utf8() {
    let payload = "héllo wörld — 日本語テスト 🚀".as_bytes().to_vec();
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok());
    assert_eq!(result.unwrap(), "héllo wörld — 日本語テスト 🚀");
}

#[test]
fn handles_invalid_utf8_with_replacement() {
    // Invalid UTF-8: 0xFF is not a valid continuation byte
    let payload = vec![0x66, 0x6F, 0xFF, 0x6F]; // "fo\xFFo"
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok(), "invalid UTF-8 should be lossy-converted");
    let output = result.unwrap();
    // Lossy conversion replaces invalid bytes with U+FFFD
    assert!(output.contains('\u{FFFD}'));
    assert!(output.starts_with("fo"));
    assert!(output.ends_with('o'));
}

#[test]
fn handles_empty_payload() {
    let result = sanitize_chat_input(b"");
    assert!(result.is_ok());
    assert_eq!(result.unwrap(), "");
}

#[test]
fn handles_ascii_control_characters() {
    let payload = b"line1\nline2\twith\ttabs\r\n".to_vec();
    let result = sanitize_chat_input(&payload);
    assert!(result.is_ok());
    let output = result.unwrap();
    assert!(output.contains('\n'));
    assert!(output.contains('\t'));
}

