#[test]
fn handles_concurrent_sanitization() {
    use std::thread;

    let handles: Vec<_> = (0..16)
        .map(|i| {
            thread::spawn(move || {
                let payload = format!("message-{} with some content", i).into_bytes();
                for _ in 0..100 {
                    let result = sanitize_chat_input(&payload);
                    assert!(result.is_ok());
                }
            })
        })
        .collect();

    for handle in handles {
        handle.join().expect("thread panicked");
    }
}

#[test]
fn stress_test_large_payloads() {
    // Simulate high-throughput with mixed sizes
    let mut rng = rand::thread_rng();
    for _ in 0..1000 {
        let size = rng.gen_range(0..MAX_PAYLOAD_BYTES + 2048);
        let payload: Vec<u8> = (0..size).map(|_| rng.gen()).collect();
        let _ = sanitize_chat_input(&payload);
    }
}

